describe("formatted", () => {
  test("new snapshots", async () => {
    expect({ a: 1, b: ["x", "y"] }).toMatchInlineSnapshot(`
     {
       "a": 1,
       "b": [
         "x",
         "y",
       ],
     }
    `)
    expect("one line").toMatchInlineSnapshot(`"one line"`)
    await expect(Promise.resolve({ deep: { ok: true } })).resolves
      .toMatchInlineSnapshot(`
     {
       "deep": {
         "ok": true,
       },
     }
    `)
  })
})
